for (const code in TD) Object.assign(T[code], TD[code]);

let lang = "it";
try {
  const saved = localStorage.getItem(KEY);
  if (saved && (saved === "it" || T[saved])) lang = saved;
  else {
    const nav = (navigator.language || "it").slice(0, 2);
    if (nav === "it" || T[nav]) lang = nav;
  }
} catch (e) {}

export function getLang() { return lang; }
export function setLang(code) {
  lang = code;
  try { localStorage.setItem(KEY, code); } catch (e) {}
  applyStaticTranslations();
}

// t(chiave_italiana, {param}) → traduzione con sostituzione {param}
export function t(it, params) {
  let s = (lang === "it" || !T[lang] || T[lang][it] == null) ? it : T[lang][it];
  if (params) for (const k in params) s = s.split("{" + k + "}").join(params[k]);
  return s;
}

// Traduce gli elementi statici marcati con data-i18n (usa il testo IT come chiave)
export function applyStaticTranslations() {
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n");
    const val = t(key);
    if (el.hasAttribute("data-i18n-html")) el.innerHTML = val;
    else el.textContent = val;
  });
  document.querySelectorAll("[data-i18n-ph]").forEach((el) => {
    el.setAttribute("placeholder", t(el.getAttribute("data-i18n-ph")));
  });
}
